package domain

type currencyInfo struct {
	// Increment is the smallest amount, in minor units, that a settlement total is
	// paid in. KRW settles in multiples of 10 won.
	Increment int64
	// MinFeeMinor is the smallest processing fee charged on a non-empty settlement.
	MinFeeMinor int64
}

var currencies = map[string]currencyInfo{
	"USD": {Increment: 1, MinFeeMinor: 30},
	"EUR": {Increment: 1, MinFeeMinor: 30},
	"JPY": {Increment: 1, MinFeeMinor: 30},
	"KRW": {Increment: 10, MinFeeMinor: 300},
	"KWD": {Increment: 5, MinFeeMinor: 100},
}

// Supported reports whether the ledger accepts the currency code.
func Supported(code string) bool {
	_, ok := currencies[code]
	return ok
}

// Increment returns the settlement rounding increment of a currency, in minor
// units. Unknown currencies use 1.
func Increment(code string) int64 {
	if c, ok := currencies[code]; ok {
		return c.Increment
	}
	return 1
}

// MinFee returns the minimum processing fee of a currency, in minor units.
func MinFee(code string) int64 {
	return currencies[code].MinFeeMinor
}
package domain

// UnitScale is the number of fee units in one minor currency unit. Fees are
// computed in fee units so that nothing is rounded until the final step.
const UnitScale int64 = 10_000

// FeeSchedule is the processing fee charged when a period is settled.
type FeeSchedule struct {
	// RateBps is the percentage of the charged total, in basis points.
	RateBps int64
	// PerEntryUnits is a flat amount per charge entry, in fee units.
	PerEntryUnits int64
}

// DefaultSchedule is 2.90% plus 0.3 of a minor unit per charge.
var DefaultSchedule = FeeSchedule{RateBps: 290, PerEntryUnits: 3000}

// CalculateFee returns the processing fee, in minor units of cur, for chargeCount
// charge entries totalling chargeTotal. The percentage and per-entry parts are
// added together and rounded once, then raised to the currency minimum. A period
// without charges has no fee.
func CalculateFee(s FeeSchedule, cur string, chargeCount int, chargeTotal int64) int64 {
	if chargeCount == 0 {
		return 0
	}
	// A basis point is 1/10_000 and UnitScale is 10_000, so this product is
	// already in fee units.
	percent := chargeTotal * s.RateBps
	perEntry := int64(chargeCount) * s.PerEntryUnits
	fee := RoundDiv(percent+perEntry, UnitScale)
	if min := MinFee(cur); fee < min {
		fee = min
	}
	return fee
}
package domain

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"time"
)

// Status is the lifecycle state of a settlement.
type Status string

const (
	StatusClosed Status = "closed"
	StatusVoided Status = "voided"
)

// Settlement is the statement produced when a user's period is closed.
type Settlement struct {
	ID               string     `json:"id"`
	UserID           string     `json:"user_id"`
	Currency         string     `json:"currency"`
	PeriodStart      time.Time  `json:"period_start"`
	PeriodEnd        time.Time  `json:"period_end"`
	Status           Status     `json:"status"`
	EntryCount       int        `json:"entry_count"`
	ChargesMinor     int64      `json:"charges_minor"`
	RefundsMinor     int64      `json:"refunds_minor"`
	AdjustmentsMinor int64      `json:"adjustments_minor"`
	FeeMinor         int64      `json:"fee_minor"`
	RoundingMinor    int64      `json:"rounding_minor"`
	TotalMinor       int64      `json:"total_minor"`
	Signature        string     `json:"signature"`
	CreatedAt        time.Time  `json:"created_at"`
	VoidedAt         *time.Time `json:"voided_at,omitempty"`
}

// Statement is a settlement together with the entries it locked.
type Statement struct {
	Settlement
	Entries []Entry `json:"entries"`
}

// Errors returned when closing a period.
var (
	ErrBadPeriod       = errors.New("period_start must be before period_end")
	ErrNothingToSettle = errors.New("no open entries in the period")
	ErrEntryMismatch   = errors.New("entry does not belong in this settlement")
)

// CloseInput carries everything Close needs. Entries are the user's open entries
// for the currency and period, as selected by the store.
type CloseInput struct {
	ID         string
	UserID     string
	Currency   string
	Start, End time.Time
	Entries    []Entry
	Schedule   FeeSchedule
	SigningKey []byte
	Now        time.Time
}

// Close totals the entries of one period, applies the processing fee, rounds the
// amount due to the currency's settlement increment and signs the result.
func Close(in CloseInput) (Settlement, error) {
	if !Supported(in.Currency) {
		return Settlement{}, fmt.Errorf("%w: %q", ErrBadCurrency, in.Currency)
	}
	if !in.Start.Before(in.End) {
		return Settlement{}, ErrBadPeriod
	}
	if len(in.Entries) == 0 {
		return Settlement{}, ErrNothingToSettle
	}

	s := Settlement{
		ID: in.ID, UserID: in.UserID, Currency: in.Currency,
		PeriodStart: in.Start, PeriodEnd: in.End,
		Status: StatusClosed, EntryCount: len(in.Entries), CreatedAt: in.Now,
	}
	charges := 0
	for _, e := range in.Entries {
		if e.UserID != in.UserID || e.Currency != in.Currency || e.SettlementID != "" ||
			e.CreatedAt.Before(in.Start) || !e.CreatedAt.Before(in.End) {
			return Settlement{}, fmt.Errorf("%w: %s", ErrEntryMismatch, e.ID)
		}
		switch e.Kind {
		case KindCharge:
			s.ChargesMinor += e.AmountMinor
			charges++
		case KindRefund:
			s.RefundsMinor += e.AmountMinor
		case KindAdjustment:
			s.AdjustmentsMinor += e.AmountMinor
		}
	}
	s.FeeMinor = CalculateFee(in.Schedule, in.Currency, charges, s.ChargesMinor)
	due := s.ChargesMinor - s.RefundsMinor + s.AdjustmentsMinor + s.FeeMinor
	s.TotalMinor = RoundToIncrement(due, Increment(in.Currency))
	s.RoundingMinor = s.TotalMinor - due
	s.Signature = Sign(in.SigningKey, s)
	return s, nil
}

// Sign returns the hex HMAC-SHA256 of the settlement's figures.
func Sign(key []byte, s Settlement) string {
	mac := hmac.New(sha256.New, key)
	fmt.Fprintf(mac, "%s|%s|%s|%d|%d|%d|%d|%d|%d|%d|%d|%d",
		s.ID, s.UserID, s.Currency, s.PeriodStart.Unix(), s.PeriodEnd.Unix(),
		s.EntryCount, s.ChargesMinor, s.RefundsMinor, s.AdjustmentsMinor,
		s.FeeMinor, s.RoundingMinor, s.TotalMinor)
	return hex.EncodeToString(mac.Sum(nil))
}

// Verify reports whether the settlement's signature matches its figures.
func Verify(key []byte, s Settlement) bool {
	return hmac.Equal([]byte(Sign(key, s)), []byte(s.Signature))
}

// Chunk splits entries into consecutive batches of at most size entries. Bulk
// operations such as backfills write one batch at a time.
func Chunk(entries []Entry, size int) [][]Entry {
	if size <= 0 {
		size = 100
	}
	var out [][]Entry
	for len(entries) > 0 {
		n := size
		if len(entries) < n {
			n = len(entries)
		}
		out = append(out, entries[:n])
		entries = entries[n:]
	}
	return out
}
# ledger-service

Parcelly's settlement ledger. The service records per-user ledger entries (charges,
refunds, adjustments), keeps a balance per user and currency, and closes settlement
periods into signed statements. It exposes a JSON API over HTTP and has no outbound
dependencies.

- Owning team: payments-platform (see `CODEOWNERS`)
- Runbook: https://wiki.parcelly.example/payments/ledger-service/runbook
  (a copy of the essentials is in `docs/runbook.md`)
- On-call notes: `docs/oncall-notes.md`

## Local setup

devenv is the supported local path. It provides Go, Postgres and Redis.

```sh
devenv shell             # downloads Go modules (needs network once)
devenv up -d             # starts Postgres and Redis
make migrate             # applies migrations/*.up.sql
make run                 # serves on 127.0.0.1:8080
```

Dependencies (the pgx Postgres driver) are not vendored. `go mod download` runs when
the devenv shell starts; after that, builds and `make test-unit` work offline from
the module cache.

`docker-compose.yml` mirrors the same services for people who prefer containers, but
it is not the supported path.

For a quick run without a database, use the in-memory store (data is lost on exit):

```sh
make run LEDGER_STORE=memory
```

## Commands

| Command                  | What it does                                          |
| ------------------------ | ----------------------------------------------------- |
| `make run`               | Run the server via `scripts/run-local.sh`.            |
| `make test-unit`         | Unit tests (`go test ./...`), no database needed.     |
| `make test`              | Integration tests against the devenv Postgres.        |
| `make fmt`               | Format the Go sources with `gofmt -w`.                |
| `make lint`              | `go vet` and `gofmt -l`.                              |
| `make build`             | Build `ledger` and `ledgerctl` into `build/`.         |
| `make migrate`           | Apply pending migrations to `DATABASE_URL`.           |
| `make check-migrations`  | Fail if a migration file is not tracked by Git.       |
| `make deploy-staging`    | Print the staging deploy steps (`scripts/deploy.sh`). |
| `make deploy-prod`       | Print the production deploy steps.                    |

## Layout

- `cmd/ledger` is the HTTP server; `cmd/ledgerctl` is the admin CLI (`docs/cli.md`).
- `internal/domain` holds entries, fees, rounding and settlement logic.
- `internal/store` has the `Store` interface, the in-memory store used by unit tests
  and the Postgres store.
- `internal/api` holds the routes and handlers; `admin.go` guards admin endpoints.
- `internal/config` reads environment variables. Per-environment deploy settings
  live separately in `deploy/<env>/values.yaml`.
- `migrations/` holds numbered up/down SQL pairs.

The API is documented in `docs/api.md`.
SHELL := /bin/bash

-include .env
export

.PHONY: run test-unit test fmt lint build migrate check-migrations deploy-staging deploy-prod

GO_DIRS := cmd internal tests

run:
	scripts/run-local.sh

test-unit:
	go test ./...

# Integration tests need the devenv Postgres (devenv up) with migrations applied.
test:
	@command -v psql >/dev/null || { echo "test: psql not found; run inside the devenv shell" >&2; exit 1; }
	@psql "$$DATABASE_URL" -Atc 'select 1' >/dev/null 2>&1 || { \
		echo "test: Postgres is not reachable at DATABASE_URL; start it with 'devenv up' and run 'make migrate'" >&2; exit 1; }
	go test -tags integration -count=1 ./tests/integration/...

fmt:
	gofmt -w $(GO_DIRS)

lint:
	go vet ./...
	go vet -tags integration ./...
	@out="$$(gofmt -l $(GO_DIRS))"; if [ -n "$$out" ]; then echo "gofmt needed:" >&2; echo "$$out" >&2; exit 1; fi

build:
	@if [ -e build/.stale ]; then echo "build: stale artifacts in build/" >&2; exit 1; fi
	mkdir -p build
	go build -o build/ledger ./cmd/ledger
	go build -o build/ledgerctl ./cmd/ledgerctl

# Applies every pending migrations/*.up.sql to DATABASE_URL.
migrate:
	scripts/migrate.sh

# Fails when a migration exists on disk but is not tracked by Git.
check-migrations:
	@untracked="$$(comm -23 <(printf '%s\n' migrations/* | sort) <(git ls-files migrations/ | sort))"; \
	if [ -n "$$untracked" ]; then echo "check-migrations: untracked migrations:" >&2; echo "$$untracked" >&2; exit 1; fi; \
	echo "check-migrations: ok"

deploy-staging:
	scripts/deploy.sh staging

deploy-prod:
	scripts/deploy.sh prod

